import importlib.util
import io
import json
from pathlib import Path
import shutil
import tempfile
import unittest
from contextlib import redirect_stdout

SCRIPT = Path(__file__).resolve().parents[1] / 'scripts' / 'go_toolkit.py'
spec = importlib.util.spec_from_file_location('go_toolkit', SCRIPT)
toolkit = importlib.util.module_from_spec(spec)
spec.loader.exec_module(toolkit)

GO_MOD = '''module github.com/acme/payments // comment

go 1.23.4

toolchain go1.24.2

require github.com/stretchr/testify v1.9.0

require (
	go.uber.org/fx v1.22.0
	golang.org/x/sync v0.8.0
	github.com/davecgh/go-spew v1.1.1 // indirect
)

replace github.com/acme/shared => ../shared

tool golang.org/x/tools/cmd/stringer
'''


class ParseTests(unittest.TestCase):
    def test_go_mod(self):
        mod = toolkit.parse_go_mod(GO_MOD)
        self.assertEqual(mod['module'], 'github.com/acme/payments')
        self.assertEqual(mod['go'], '1.23.4')
        self.assertEqual(mod['toolchain'], 'go1.24.2')
        self.assertEqual([r['path'] for r in mod['require']],
                         ['github.com/stretchr/testify', 'go.uber.org/fx', 'golang.org/x/sync',
                          'github.com/davecgh/go-spew'])
        self.assertEqual([r['indirect'] for r in mod['require']], [False, False, False, True])
        self.assertEqual(mod['replace'], [{'from': 'github.com/acme/shared', 'to': '../shared'}])
        self.assertEqual(mod['tool'], ['golang.org/x/tools/cmd/stringer'])

    def test_versions_and_targets(self):
        self.assertEqual(toolkit.parse_version('1.21'), [1, 21])
        self.assertEqual(toolkit.parse_version('1.23.4'), [1, 23])
        self.assertEqual(toolkit.parse_version('go1.24rc1'), [1, 24])
        self.assertIsNone(toolkit.parse_version('latest'))
        self.assertEqual(toolkit.make_targets('VAR := 1\n.PHONY: test\ntest:\n\tgo test\nlint: fmt\n'),
                         ['test', 'lint'])
        self.assertEqual(toolkit.taskfile_tasks('version: "3"\ntasks:\n  test:\n    cmds: []\n  lint:\n    cmds: []\n'),
                         ['test', 'lint'])
        self.assertEqual(toolkit.parse_go_work('go 1.23\nuse (\n\t./api\n\t./worker\n)\n')['use'],
                         ['./api', './worker'])


class DiscoverTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)

    def test_discovers_module_signals_without_executing_go(self):
        module = self.root / 'svc'
        (module / 'internal' / 'usecase').mkdir(parents=True)
        (module / 'cmd' / 'api').mkdir(parents=True)
        (module / 'nested').mkdir()
        (module / 'go.mod').write_text(GO_MOD)
        (module / 'Makefile').write_text('test:\n\tgo test ./...\nlint:\n\tgolangci-lint run\n')
        (module / '.golangci.yml').write_text('version: "2"\n')
        (module / 'cmd' / 'api' / 'main.go').write_text('package main\n\nfunc main() {}\n')
        (module / 'internal' / 'usecase' / 'pay.go').write_text(
            '//go:build !integration\n\npackage usecase\n\n//go:generate stringer -type=Status\ntype Status int\n')
        (module / 'internal' / 'usecase' / 'mock.go').write_text(
            '// Code generated by MockGen. DO NOT EDIT.\npackage usecase\n')
        (module / 'nested' / 'go.mod').write_text('module other\n\ngo 1.22\n')
        (module / 'nested' / 'x.go').write_text('package other\n')
        result = toolkit.discover(module / 'internal')
        self.assertTrue(result['go_module'])
        self.assertEqual(result['module_dir'], str(module.resolve()))
        self.assertEqual(result['language_version'], [1, 23])
        self.assertEqual(result['toolchain'], 'go1.24.2')
        self.assertEqual(result['signals'], ['errgroup', 'fx', 'testify'])
        self.assertEqual(result['make_targets'], ['test', 'lint'])
        self.assertTrue(result['lint_config'].endswith('.golangci.yml'))
        self.assertEqual(result['packages'], 2)  # nested module is excluded
        self.assertEqual(result['generated_files'], 1)
        self.assertEqual(result['go_generate'][0]['command'], 'stringer -type=Status')
        self.assertEqual(result['build_tags'], ['integration'])
        self.assertIn('usecase', result['layer_dirs'])
        self.assertTrue(result['layout']['cmd'] and result['layout']['internal'])

    def test_non_module_and_invalid_path(self):
        self.assertFalse(toolkit.discover(self.root)['go_module'])
        with self.assertRaises(toolkit.InputError):
            toolkit.discover(self.root / 'missing')
        out = io.StringIO()
        with redirect_stdout(out):
            self.assertEqual(toolkit.main(['discover', str(self.root)]), 1)
            self.assertEqual(toolkit.main(['discover', str(self.root / 'missing')]), 2)


class FakeRunner:
    def __init__(self, responses):
        self.responses = responses
        self.commands = []

    def __call__(self, command, cwd, timeout):
        self.commands.append(command)
        for prefix, response in self.responses:
            if command[:len(prefix)] == prefix:
                return response
        return 0, ''


class ValidateTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.module = Path(self.temp.name)
        (self.module / 'go.mod').write_text('module example.com/x\n\ngo 1.22\n')
        (self.module / 'x.go').write_text('package x\n')

    def which(self, name):
        return '/usr/bin/' + name

    def test_ladder_is_read_only_and_reports_failures(self):
        runner = FakeRunner([
            (['go', 'version'], (0, 'go version go1.22.2 linux/amd64\n')),
            (['go', 'env'], (0, 'linux\namd64\n1\nlocal\n\n')),
            (['go', 'list'], (0, str(self.module) + '\tx.go x_test.go \n')),
            (['gofmt'], (0, '')),
            (['go', 'test'], (1, '--- FAIL: TestX (0.00s)\nFAIL\texample.com/x\t0.01s\n')),
        ])
        result = toolkit.validate(self.module, ['./...'], runner=runner, which=self.which)
        by_check = {c['check']: c for c in result['checks']}
        self.assertEqual(by_check['gofmt']['result'], 'passed')
        self.assertEqual(by_check['vet']['result'], 'passed')
        self.assertEqual(by_check['build']['result'], 'passed')
        self.assertEqual(by_check['test']['result'], 'failed')
        self.assertIn('TestX', by_check['test']['summary'])
        self.assertFalse(result['passed'])
        self.assertEqual(result['context']['cgo_enabled'], '1')
        for command in runner.commands:
            self.assertNotIn('-w', command)
            if command[:2] == ['go', 'build']:
                self.assertIn('-o', command)
            if command[:2] == ['go', 'test']:
                self.assertIn('-count=1', command)

    def test_unavailable_tools_are_not_run_and_lint_is_never_created(self):
        result = toolkit.validate(self.module, None, lint=True, runner=FakeRunner([]),
                                  which=lambda name: None)
        self.assertEqual({c['result'] for c in result['checks']}, {'not_run'})
        self.assertFalse(result['passed'])
        result = toolkit.validate(self.module, None, lint=True, runner=FakeRunner([
            (['go', 'list'], (0, str(self.module) + '\tx.go\n'))]), which=self.which)
        lint = [c for c in result['checks'] if c['check'] == 'lint'][0]
        self.assertEqual(lint['result'], 'not_run')
        self.assertFalse((self.module / '.golangci.yml').exists())

    def test_race_without_cgo_is_not_run(self):
        runner = FakeRunner([
            (['go', 'list'], (0, str(self.module) + '\tx.go\n')),
            (['go', 'test', '-count=1', '-race'], (2, 'go: -race requires cgo; enable cgo by setting CGO_ENABLED=1\n')),
        ])
        result = toolkit.validate(self.module, ['./...'], race=True, runner=runner, which=self.which)
        race = [c for c in result['checks'] if c['check'] == 'race'][0]
        self.assertEqual(race['result'], 'not_run')

    def test_rejects_option_injection(self):
        for packages in (['-exec=evil'], ['./... ; rm']):
            with self.subTest(packages=packages), self.assertRaises(toolkit.InputError):
                toolkit.validate(self.module, packages, runner=FakeRunner([]), which=self.which)
        with self.assertRaises(toolkit.InputError):
            toolkit.validate(self.module, None, tags='a b', runner=FakeRunner([]), which=self.which)

    @unittest.skipUnless(shutil.which('go'), 'Go toolchain not available')
    def test_real_toolchain_against_fixture(self):
        fixture = SCRIPT.parents[1] / 'evaluations' / 'fixtures' / 'go-bugfix'
        work = self.module / 'go-bugfix'
        shutil.copytree(fixture, work)
        before = {p.name: p.read_bytes() for p in work.iterdir()}
        result = toolkit.validate(work, ['./...'])
        by_check = {c['check']: c['result'] for c in result['checks']}
        self.assertEqual(by_check, {'gofmt': 'passed', 'vet': 'passed', 'build': 'passed', 'test': 'passed'})
        self.assertEqual(before, {p.name: p.read_bytes() for p in work.iterdir()})
        out = io.StringIO()
        with redirect_stdout(out):
            self.assertEqual(toolkit.main(['discover', str(work)]), 0)
        self.assertEqual(json.loads(out.getvalue())['go_directive'], '1.21')


if __name__ == '__main__':
    unittest.main()
